async function loadDashboardData() {
  if (!state.user?.id) return;
  showSkeletonLoading('กำลังโหลดข้อมูลการประเมิน...');
  try {
    if (cloudEnabled()) {
      const res = await api('get_ethics_dashboard', { user_id: state.user.id });
      state.dashboardData = res;
      if (res.user?.role) state.user.role = res.user.role;
      localStorage.setItem('np_session', JSON.stringify(state.user));
    } else {
      state.dashboardData = getLocalDashboardFallback();
    }
  } catch (e) {
    console.error('loadDashboardData error:', e);
    state.dashboardData = getLocalDashboardFallback();
  } finally {
    hideSkeletonLoading();
    render();
  }
}

function renderDashboard() {
  if (!state.user) {
    navTo('login.html');
    return;
  }

  const role = state.user.role || 'NURSE';
  const roleName = roles[role] || role;
  const periodName = state.dashboardData?.activePeriod?.name || state.activePeriod.name;

  // Render Role-Specific Sections
  let mainContent = '';
  if (state.dashboardTab === 'account') {
    mainContent = renderAccountSettings();
  } else if (state.dashboardTab === 'all_reports') {
    mainContent = renderExecutiveReportsView();
  } else if (role === 'HEAD_NURSE') {
    mainContent = renderHeadNurseDashboard();
  } else if (role === 'GROUP_HEAD') {
    mainContent = renderGroupHeadDashboard();
  } else if (role === 'UNIT_HEAD') {
    mainContent = renderUnitHeadDashboard();
  } else {
    mainContent = renderNurseDashboard();
  }

  const collapsed = state.sidebarCollapsed;
  app.innerHTML = `
    <div class="app-layout">
      ${renderAppSidebar(state.dashboardTab || 'my_assessment')}
      <main class="app-main ${collapsed ? 'sidebar-collapsed' : ''}">
        <div class="container" style="max-width:1100px;padding:30px 24px">
          <div class="page-header">
            <div>
              <div class="eyebrow"><i class="fa-solid fa-calendar-check"></i> ${esc(periodName)}</div>
              <h2>ระบบประเมินพฤติกรรมจริยธรรมวิชาชีพ</h2>
              <p class="muted">บทบาท: <strong>${esc(roleName)}</strong> &nbsp;|&nbsp; สังกัด: ${esc(state.user.department)}</p>
            </div>
          </div>
          ${mainContent}
        </div>
        <footer class="site-footer">
          <span>&copy; 2026 Developed By Natnarinthorn &nbsp;&bull;&nbsp; Nursing Informatics System</span>
        </footer>
      </main>
    </div>
  `;
}

function switchDashboardTab(tab) {
  state.dashboardTab = tab;
  render();
}

