function setAnswer(qId, score) {
  state.answers[qId] = score;
  const storageKey = `np_ethics_answers_${state.user.id}_${state.currentAssessment.assignment_id}`;
  localStorage.setItem(storageKey, JSON.stringify(state.answers));
  document.querySelector(`#row_q_${qId}`)?.classList.remove('unanswered');
}

function saveAssessmentDraft() {
  const storageKey = `np_ethics_answers_${state.user.id}_${state.currentAssessment.assignment_id}`;
  localStorage.setItem(storageKey, JSON.stringify(state.answers));
  toast('บันทึกร่างเรียบร้อยแล้ว');
}

// Validation & Submission
async function submitAssessmentAnswers() {
  const curr = state.currentAssessment;
  if (!curr) return;

  // Check validation
  const missing = [];
  curr.questions.forEach((q, idx) => {
    const val = state.answers[q.question_id];
    if (val === undefined || val === null || val < 1 || val > 5) {
      missing.push(idx + 1);
      document.querySelector(`#row_q_${q.question_id}`)?.classList.add('unanswered');
    }
  });

  if (missing.length > 0) {
    toast(`กรุณาตอบข้อที่ยังไม่ได้ประเมิน (ข้อที่ ${missing.slice(0, 8).join(', ')}${missing.length > 8 ? ' ...' : ''})`);
    // Scroll to first missing row
    const firstMissingId = curr.questions[missing[0] - 1].question_id;
    document.querySelector(`#row_q_${firstMissingId}`)?.scrollIntoView({ behavior: 'smooth', block: 'center' });
    return;
  }

  // Confirm dialog
  modal(
    'ยืนยันการส่งผลการประเมิน',
    `
      <div class="confirm-modal-body">
        <p>ท่านได้ตอบข้อคำถามครบถ้วนทั้ง <strong>${curr.questions.length} ข้อ</strong> แล้ว</p>
        <p class="muted">เมื่อยืนยันส่งผลการประเมิน ข้อมูลจะถูกบันทึกเข้าระบบอย่างเป็นทางการและไม่สามารถแก้ไขได้</p>
      </div>
    `,
    `
      <div class="confirm-actions">
        <button class="btn outline" onclick="closeModal()">ยกเลิก</button>
        <button class="btn" onclick="executeSubmit()"><i class="fa-solid fa-check"></i> ยืนยันการส่ง</button>
      </div>
    `
  );
}

async function executeSubmit() {
  closeModal();
  showSkeletonLoading('กำลังบันทึกผลการประเมิน...');
  const curr = state.currentAssessment;

  const payloadAnswers = curr.questions.map(q => ({
    question_id: q.question_id,
    question_pair_id: q.question_pair_id,
    question_order: q.question_order,
    score: state.answers[q.question_id]
  }));

  try {
    if (cloudEnabled() && curr.assignment_id && !curr.assignment_id.startsWith('new_')) {
      await api('submit_ethics_assessment', {
        assignment_id: curr.assignment_id,
        evaluator_id: state.user.id,
        answers: payloadAnswers
      });
    }
    
    // Save local submission record for instant feedback
    const localResultKey = `np_ethics_sub_${curr.targetUser.id || curr.targetUser.name}_${curr.assessmentType}`;
    localStorage.setItem(localResultKey, JSON.stringify({
      answers: state.answers,
      submittedAt: new Date().toISOString(),
      evaluatorName: state.user.name,
      evaluatorRole: state.user.role
    }));

    hideSkeletonLoading();
    toast('ส่งผลการประเมินเรียบร้อยแล้ว');
    navTo('dashboard.html');
  } catch (e) {
    hideSkeletonLoading();
    console.error(e);
    toast('เกิดข้อผิดพลาดในการบันทึกข้อมูล กรุณาลองใหม่อีกครั้ง');
  }
}

// ----------------------------------------------------
// 5. INDIVIDUAL REPORT & COMPARISON (รายงานผลรายบุคคล)
// ----------------------------------------------------
async function viewMyReport(targetUserId) {
  showSkeletonLoading('กำลังเปิดรายงานผลการประเมิน...');
  try {
    if (cloudEnabled()) {
      const res = await api('get_individual_report', { target_user_id: targetUserId });
      state.activeReport = res;
    } else {
      state.activeReport = getMockIndividualReport(targetUserId);
    }
  } catch (e) {
    console.warn('API get_individual_report failed, using fallback:', e);
    state.activeReport = getMockIndividualReport(targetUserId);
  } finally {
    hideSkeletonLoading();
    renderIndividualReportModal();
  }
}

function getMockIndividualReport(targetUserId) {
  const u = users.find(x => x.id === targetUserId) || state.user;
  const pairs = ETHICS_QUESTION_BANK.nursePairs;
  
  const comparison = pairs.map(p => {
    const s = 4 + (p.order % 2 === 0 ? 1 : 0);
    const o = 4 + (p.order % 3 === 0 ? 1 : -1);
    return {
      order: p.order,
      pair_code: p.pair_code,
      self_question: p.self_text,
      self_score: s,
      other_question: p.other_text,
      other_score: o,
      difference: o - s
    };
  });

  return {
    targetProfile: {
      id: targetUserId,
      full_name: u.name || 'พยาบาลวิชาชีพ',
      position: u.position || 'พยาบาลวิชาชีพ',
      role: u.role || 'NURSE',
      departments: { name: u.department || 'งานการพยาบาลผู้ป่วยนอก' }
    },
    period: { name: 'ประจำปี 2569' },
    selfResponse: {
      total_score: 272,
      average_score: 4.25,
      item_count: 64,
      submitted_at: new Date().toISOString(),
      evaluator: { full_name: u.name, position: u.position }
    },
    otherResponse: {
      total_score: 253,
      average_score: 3.95,
      item_count: 64,
      submitted_at: new Date().toISOString(),
      evaluator: { full_name: 'นางสาวหัวหน้างาน ปฏิบัติการ', position: 'หัวหน้างาน' }
    },
    totalDiff: -0.30,
    comparison
  };
}

