async function loadExecutiveData() {
  showSkeletonLoading('กำลังประมวลผลรายงานผู้บริหาร...');
  try {
    if (cloudEnabled()) {
      const res = await api('get_executive_report');
      state.executiveData = res;
    } else {
      state.executiveData = getMockExecutiveData();
    }
  } catch (e) {
    console.error(e);
    state.executiveData = getMockExecutiveData();
  } finally {
    hideSkeletonLoading();
    render();
  }
}

