function exportSummaryExcel() {
  if (typeof XLSX === 'undefined') return toast('ไลบรารีสำหรับสร้าง Excel กำลังโหลด กรุณาลองใหม่');
  showSkeletonLoading('กำลังสร้างไฟล์ Excel สรุปผล...');

  const data = state.executiveData;
  const rows = [
    ['รายงานสรุปผลการประเมินพฤติกรรมจริยธรรมวิชาชีพของพยาบาล', '', '', '', '', '', ''],
    ['กลุ่มการพยาบาล โรงพยาบาลสมเด็จพระยุพราชสว่างแดนดิน', '', '', '', '', '', ''],
    ['รอบการประเมิน: ' + state.activePeriod.name, '', '', '', '', '', ''],
    [],
    ['ตำแหน่ง / บทบาท', 'จำนวนบุคลากร', 'Self เสร็จ (คน)', 'Other เสร็จ (คน)', 'คะแนนเฉลี่ย Self', 'คะแนนเฉลี่ย Other', 'ผลต่าง (Difference)']
  ];

  (data?.roleSummary || []).forEach(r => {
    rows.push([
      r.role_label,
      r.total_users,
      r.self_completed,
      r.other_completed,
      r.self_avg !== null ? r.self_avg.toFixed(2) : '—',
      r.other_avg !== null ? r.other_avg.toFixed(2) : '—',
      r.difference !== null ? (r.difference > 0 ? '+' : '') + r.difference.toFixed(2) : '—'
    ]);
  });

  rows.push([]);
  rows.push(['หน่วยงาน / หอผู้ป่วย', 'จำนวนบุคลากร', 'Self เสร็จ (คน)', 'Other เสร็จ (คน)', 'คะแนนเฉลี่ย Self', 'คะแนนเฉลี่ย Other', 'ผลต่าง (Difference)']);

  (data?.departmentSummary || []).forEach(d => {
    rows.push([
      d.department,
      d.total_users,
      d.self_completed,
      d.other_completed,
      d.self_avg !== null ? d.self_avg.toFixed(2) : '—',
      d.other_avg !== null ? d.other_avg.toFixed(2) : '—',
      d.difference !== null ? (d.difference > 0 ? '+' : '') + d.difference.toFixed(2) : '—'
    ]);
  });

  const ws = XLSX.utils.aoa_to_sheet(rows);
  const wb = XLSX.utils.book_new();
  XLSX.utils.book_append_sheet(wb, ws, 'Summary_Report');
  XLSX.writeFile(wb, `รายงานสรุปการประเมินจริยธรรม_รพร_สว่างแดนดิน.xlsx`);
  hideSkeletonLoading();
  toast('ดาวน์โหลด Excel เรียบร้อยแล้ว');
}

function exportDetailExcel() {
  if (typeof XLSX === 'undefined') return toast('ไลบรารี Excel กำลังโหลด กรุณาลองใหม่');
  showSkeletonLoading('กำลังสร้างไฟล์ Excel รายละเอียดรายข้อ...');

  const pairs = ETHICS_QUESTION_BANK.nursePairs;
  const rows = [
    ['ลำดับข้อ', 'รหัสคู่คำถาม', 'ข้อคำถามประเมินตนเอง (Self Question)', 'ข้อคำถามประเมินโดยผู้อื่น (Other Question)']
  ];

  pairs.forEach(p => {
    rows.push([p.order, p.pair_code, p.self_text, p.other_text]);
  });

  const ws = XLSX.utils.aoa_to_sheet(rows);
  const wb = XLSX.utils.book_new();
  XLSX.utils.book_append_sheet(wb, ws, 'Question_Pairs_Mapping');
  XLSX.writeFile(wb, `ตารางคู่คำถามจริยธรรม_QuestionPairs.xlsx`);
  hideSkeletonLoading();
  toast('ดาวน์โหลด Excel รายละเอียดรายข้อเรียบร้อยแล้ว');
}

